('12-M2A-CN-0001','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Definition','Easy',0,NULL,'The imaginary unit i is defined as','√(−1)','√1','0','−1','A','i² = −1 by definition.',NULL,1,NOW()),
('12-M2A-CN-0002','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Form','Easy',0,NULL,'Standard form of complex number is','a + bi (a,b real)','a + b','ai + b','a/b','A','Real part a, imaginary part b.',NULL,1,NOW()),
('12-M2A-CN-0003','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Conjugate','Easy',0,NULL,'Conjugate of z = 3 + 4i is','3 − 4i','3 + 4i','−3 + 4i','−3 − 4i','A','Change sign of imaginary part.',NULL,1,NOW()),
('12-M2A-CN-0004','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Modulus','Medium',0,NULL,'Modulus of z = 3 + 4i is','5','7','1','25','A','|z| = √(3²+4²) = √25 = 5.',NULL,1,NOW()),
