('12-M2A-CN-0006','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','i Powers','Easy',0,NULL,'Value of i⁴ is','1','i','−1','−i','A','i¹=i, i²=−1, i³=−i, i⁴=1 (cyclic period 4).',NULL,1,NOW()),
('12-M2A-CN-0007','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','i Powers','Medium',1,2019,'Value of i²⁵ is','i','−i','1','−1','A','25 = 4×6+1, so i²⁵ = i¹ = i.',NULL,1,NOW()),
('12-M2A-CN-0008','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Argand','Medium',0,NULL,'Complex number a+bi is represented on Argand plane as','Point (a,b)','Point (b,a)','Line','Circle','A','x-axis: real, y-axis: imaginary.',NULL,1,NOW()),
('12-M2A-CN-0009','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Argument','Hard',0,NULL,'Argument of z = 1+i is','π/4 (45°)','π/2','π','0','A','θ = arctan(1/1) = π/4, first quadrant.',NULL,1,NOW()),
('12-M2A-CN-0010','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Polar','Hard',0,NULL,'Polar form of z = 1+i is','√2(cosπ/4 + i·sinπ/4)','cosπ/4+i·sinπ/4','2(cosπ/4+i·sinπ/4)','√2·e^(iπ/2)','A','r=√2, θ=π/4.',NULL,1,NOW()),
('12-M2A-CN-0011','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Division','Medium',0,NULL,'To divide complex numbers, multiply numerator and denominator by','Conjugate of denominator','Same denominator','Zero','Numerator','A','Rationalizes the denominator.',NULL,1,NOW()),
