('12-M2A-CN-0023','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Imag Part','Easy',0,NULL,'If z = 5−3i, then Im(z) = ','−3','5','3','−5','A','Imaginary part is coefficient of i.',NULL,1,NOW()),
('12-M2A-CN-0024','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Purely Real','Easy',0,NULL,'A complex number is purely real when','Imaginary part = 0','Real part = 0','Both = 0','Neither = 0','A','z = a + 0i is purely real.',NULL,1,NOW()),
('12-M2A-CN-0025','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Purely Imag','Easy',0,NULL,'A complex number is purely imaginary when','Real part = 0','Imaginary part = 0','Both = 0','Neither = 0','A','z = 0 + bi is purely imaginary.',NULL,1,NOW()),
('12-M2A-CN-0026','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','|z|²','Medium',0,NULL,'|3+4i|² = ','25','7','12','1','A','|z|² = 3²+4² = 9+16 = 25.',NULL,1,NOW()),
('12-M2A-CN-0027','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','e^(iπ)','Hard',0,NULL,'Value of e^(iπ) + 1 = ','0','2','−2','e','A','Euler identity: e^(iπ) = −1.',NULL,1,NOW()),
('12-M2A-CN-0028','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','Cube Roots Sp','Medium',0,NULL,'120° spacing of cube roots of unity on unit circle means they form a','Regular triangle (equilateral)','Square','Pentagon','Line','A','360°/3 = 120° apart.',NULL,1,NOW()),
