('12-M2A-CN-0030','TS-Inter-2,MPC,JEE','Mathematics','Complex Numbers','i×(1+i)','Medium',1,2021,'i(1+i) = ','−1+i','1−i','1+i','−1−i','A','i+i² = i−1 = −1+i.',NULL,1,NOW());
